cat > /home/eval/report.sh <<'EOF'
#!/bin/bash
# report.sh INBOX_DIR OUT_FILE
# Count recipient domains from "to"/"cc" address lists in *.json message files.
set -u

INBOX=${1:?usage: report.sh INBOX_DIR OUT_FILE}
OUT=${2:?usage: report.sh INBOX_DIR OUT_FILE}

# Emit the *.json files (base names) in LC_ALL=C name order, NUL-separated.
find "$INBOX" -maxdepth 1 -type f -name '*.json' -printf '%f\0' | sort -z |
python3 -c '
import sys, os, json, re

inbox, out = sys.argv[1], sys.argv[2]
names = [n for n in sys.stdin.buffer.read().split(b"\0") if n]

# Split an address list on top-level commas (commas inside quotes do not split).
# A display name may contain escaped quotes ("a\"b, c" <x@y>), so \\ is honored.
def split_addrs(s):
    parts, buf, inq, esc = [], [], False, False
    for ch in s:
        if esc:
            buf.append(ch); esc = False
        elif inq and ch == "\\":
            buf.append(ch); esc = True
        elif ch == "\"":
            buf.append(ch); inq = not inq
        elif ch == "," and not inq:
            parts.append("".join(buf)); buf = []
        else:
            buf.append(ch)
    parts.append("".join(buf))
    return parts

addr_re = re.compile(r"@([^\s@<>()\[\],;:]+)")

counts = {}
for n in names:
    path = os.path.join(inbox, n.decode("utf-8", "surrogateescape"))
    try:
        with open(path, "r", encoding="utf-8") as f:
            obj = json.load(f)
        if not isinstance(obj, dict):
            raise ValueError("not an object")
    except Exception:
        print("skip: " + n.decode("utf-8", "replace"), file=sys.stderr)
        continue
    for key in ("to", "cc"):
        val = obj.get(key)
        if not isinstance(val, str) or not val.strip():
            continue
        for seg in split_addrs(val):
            for m in addr_re.finditer(seg):      # each address has its own @
                d = m.group(1).strip().lower()
                if d:
                    counts[d] = counts.get(d, 0) + 1

lines = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
with open(out, "w", encoding="utf-8") as f:
    for d, c in lines:
        f.write("%d %s\n" % (c, d))
' "$INBOX" "$OUT"
EOF
chmod +x /home/eval/report.sh
echo "script written"

